INSERT INTO servicio (titulo, descripcion, precio) VALUES
    ('Consulta general', 'Evaluación completa del estado de salud de tu mascota. Incluye revisión física general, signos vitales, ojos, oídos, boca, piel, pelaje y condición corporal. También se revisan antecedentes y síntomas para determinar si requiere tratamiento, exámenes o controles adicionales. Ideal para: controles preventivos, chequeos de rutina y mascotas que presentan algún síntoma o cambio de comportamiento.', 25000),
    ('Vacunación', 'Aplicación de vacunas según la edad, especie, historial y necesidades de cada mascota. Antes de la vacunación se realiza una evaluación básica para comprobar que se encuentre en buenas condiciones y se entrega orientación sobre las próximas dosis y refuerzos (El precio puede variar según el tipo de vacuna y protocolo requerido).', 18000),
    ('Control de peso', 'Evaluación del peso y condición corporal para detectar sobrepeso, obesidad o bajo peso. Incluye recomendaciones básicas sobre alimentación, actividad física y seguimiento, adaptadas a las características y necesidades de cada mascota.', 12000),
    ('Desparasitación', 'Tratamiento preventivo contra parásitos internos y externos, seleccionado según la especie, edad, peso y estilo de vida de la mascota. También se entrega orientación sobre la frecuencia de desparasitación y medidas de prevención (El precio puede variar según el peso y producto utilizado).', 10000),
    ('Cirugia menor', 'Procedimientos quirúrgicos de baja complejidad realizados con anestesia, como sutura de heridas, extracción de pequeñas masas u otras intervenciones ambulatorias. Incluye evaluación previa y control posterior (El precio puede variar según el procedimiento requerido).', 80000);
